contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 depositAmount, uint256 refundAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(refundAmount > 0, "refund must be positive");
        require(depositAmount <= address(this).balance, "not enough balance to deposit");
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        require(refundAmount <= depositAmount, "refund must not exceed deposit");
        require(refundAmount < depositAmount, "refund must be partial (not full)");

        uint256 balanceBefore = address(c).balance;
        uint256 ethBefore = address(this).balance;

        c.refund(); if (__ESBMC_reverted()) return;

        uint256 balanceAfter = address(c).balance;
        uint256 ethAfter = address(this).balance;

        // refund() sends the caller's entire balance, so withdrawal amount = depositAmount
        assert(
            address(this).balance == ethBefore + depositAmount &&
            balanceAfter == balanceBefore - depositAmount &&
            depositAmount > 0
        );
    }
}

