// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount, uint256 refundAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(refundAmount > 0);
        vm.assume(depositAmount <= address(this).balance);
        try c.deposit{value: depositAmount}() {} catch { return; }
        vm.assume(refundAmount <= depositAmount);
        vm.assume(refundAmount < depositAmount);
        uint256 balanceBefore = address(c).balance;
        uint256 ethBefore = address(this).balance;
        try c.refund() {} catch { return; }
        uint256 balanceAfter = address(c).balance;
        uint256 ethAfter = address(this).balance;
        assertTrue(address(this).balance == ethBefore + depositAmount &&
            balanceAfter == balanceBefore - depositAmount &&
            depositAmount > 0);
    }

    function testFuzz_run(uint256 depositAmount, uint256 refundAmount) public {
        _run(depositAmount, refundAmount);
    }

    receive() external payable {}
}
